<!DOCTYPE html>
<html lang="zh-CN">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>全部课程 - 学途</title>
    <style>
        :root {
            --primary-color: #2563eb;
            --primary-dark: #1e40af;
            --secondary-color: #0f172a;
            --bg-light: #f8fafc;
            --text-main: #334155;
            --text-light: #64748b;
            --white: #ffffff;
            --border-color: #e2e8f0;
            --radius-md: 8px;
            --radius-lg: 16px;
            --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
            --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1);
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif;
            background-color: var(--bg-light);
            color: var(--text-main);
            line-height: 1.6;
        }

        a { text-decoration: none; color: inherit; transition: color 0.2s; }

        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
        }

        /* Header (Simplified for courses page) */
        header {
            background-color: var(--white);
            border-bottom: 1px solid var(--border-color);
            position: sticky;
            top: 0;
            z-index: 100;
        }

        .nav-wrapper {
            display: flex;
            justify-content: space-between;
            align-items: center;
            height: 70px;
        }

        .logo {
            font-size: 1.5rem;
            font-weight: 800;
            color: var(--primary-color);
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .nav-links {
            display: flex;
            gap: 32px;
        }

        .nav-links a {
            font-weight: 500;
            color: var(--text-main);
        }

        .nav-links a:hover {
            color: var(--primary-color);
        }

        /* Page Header */
        .page-header {
            background-color: var(--white);
            padding: 40px 0;
            border-bottom: 1px solid var(--border-color);
            margin-bottom: 40px;
        }

        .page-header h1 {
            font-size: 2rem;
            color: var(--secondary-color);
            margin-bottom: 10px;
        }

        .page-header p {
            color: var(--text-light);
        }

        /* Main Content Layout */
        .content-layout {
            display: grid;
            grid-template-columns: 240px 1fr;
            gap: 40px;
        }

        /* Sidebar Filters */
        .sidebar {
            background: var(--white);
            padding: 24px;
            border-radius: var(--radius-md);
            border: 1px solid var(--border-color);
            height: fit-content;
        }

        .filter-group {
            margin-bottom: 30px;
        }

        .filter-group h4 {
            font-size: 1rem;
            margin-bottom: 16px;
            color: var(--secondary-color);
        }

        .category-list li {
            margin-bottom: 12px;
        }

        .category-list label {
            display: flex;
            align-items: center;
            gap: 8px;
            cursor: pointer;
            color: var(--text-main);
        }

        .price-range {
            margin-top: 20px;
        }

        .price-options label {
            display: block;
            margin-bottom: 8px;
        }

        .category-list input[type="checkbox"], .price-options input[type="radio"] {
            accent-color: var(--primary-color);
            width: 16px;
            height: 16px;
        }

        /* Course List */
        .course-list-container {
            display: flex;
            flex-direction: column;
            gap: 24px;
        }

        .course-list-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-bottom: 2px solid var(--bg-light);
            padding-bottom: 12px;
        }

        .result-count {
            color: var(--text-light);
            font-size: 0.95rem;
        }

        .sort-select {
            padding: 6px 12px;
            border: 1px solid var(--border-color);
            border-radius: var(--radius-md);
            background-color: var(--white);
            color: var(--text-main);
        }

        .course-card {
            display: flex;
            background: var(--white);
            border: 1px solid var(--border-color);
            border-radius: var(--radius-md);
            overflow: hidden;
            box-shadow: var(--shadow-sm);
            transition: box-shadow 0.2s;
        }

        .course-card:hover {
            box-shadow: var(--shadow-md);
        }

        .course-img {
            width: 200px;
            object-fit: cover;
        }

        .course-details {
            padding: 20px;
            flex: 1;
        }

        .course-badge {
            display: inline-block;
            padding: 4px 8px;
            background-color: #e0f2fe;
            color: #0369a1;
            font-size: 0.75rem;
            border-radius: 4px;
            margin-bottom: 8px;
            font-weight: 600;
        }

        .course-title {
            font-size: 1.15rem;
            font-weight: 700;
            color: var(--secondary-color);
            margin-bottom: 8px;
        }

        .course-desc {
            color: var(--text-light);
            font-size: 0.9rem;
            margin-bottom: 16px;
            display: -webkit-box;
            -webkit-line-clamp: 2;
            -webkit-box-orient: vertical;
            overflow: hidden;
